def debit_clamp(amount):
    if amount < 0:
        return 0
    return amount

from clamp import debit_clamp


def test_negative_clamped_to_zero():
    result = debit_clamp(-3)
    if result != 0:
        raise AssertionError("negative amounts must clamp to zero")


def test_positive_passthrough():
    result = debit_clamp(5)
    if result != 5:
        raise AssertionError("non-negative amounts must pass through unchanged")
